{"source":"#include<stdio.h>
int main(int argc, char *argv[])
{
    int n,a,b,c,t[40010] = {0};
    scanf("%d %d %d %d",&n,&a,&b,&c);
    t[0] = 1;
    for(int i = 0; i <= n; i++)
    {
        if(t[i] == 1)
        {
            if(i + a <= n && t[i + a] < t[i] + 1)
            t[i + a] = t[i] + 1; 
            if(i + b <= n && t[i + b] < t[i] + 1)
            t[i + b] = t[i] + 1; 
            if(i + c <= n && t[i + c] < t[i] + 1)
            t[i + c] = t[i] + 1; 
        }
    }
    printf("%d\n",t[n]);
return 0;
}"}
